	public bool HasBattleActionInteractionEnum(BattleActionInteractionEnum battleActionInteractionEnum)
	{
		if (battleActionInteractionEnum == BattleActionInteractionEnum.PURIFY && notAffectedByEmpower && ReferenceSingleton<CellariusOmensHandler>.Instance.NadirRingOmenActive)
		{
			return true;
		}
		return battleActionInteractionEnums.Contains(battleActionInteractionEnum);
	}

	public bool HasMandatoryBattleActionInteractionEnum()
	{
		for (int i = 0; i < battleActionInteractionEnums.Count; i++)
		{
			if (mandatoryBattleActionInteractionEnums.Contains(battleActionInteractionEnums[i]))
			{
				return true;
			}
		}
		return false;
	}

	public string GetActionName(BattleAction battleAction)
	{
		if (modded)
		{
			return battleAction.name;
		}
		if (enableCustomName)
		{
			return customBattleActionName.GetActionName(battleAction);
		}
		string text = GetLocalizedString(actionIDName);
		if (battleAction.Locked && !battleAction.DontAddLockedToName)
		{
			if ((bool)battleAction.TargetData && !disableTargetOnName && battleAction.TargetData.EnableTargetNameID)
			{
				text = Smart.Format(GetLocalizedString(battleAction.TargetData.TargetNameID), text);
			}
			text = Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedLockedAction(), text);
		}
		else if (battleAction.NonForgeable && !battleAction.DontAddUnforgeableToName)
		{
			if ((bool)battleAction.TargetData && !disableTargetOnName && battleAction.TargetData.EnableTargetNameID)
			{
				text = Smart.Format(GetLocalizedString(battleAction.TargetData.TargetNameID), text);
			}
			text = Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedUnforgeable(), text);
		}
		else if ((bool)battleAction.TargetData && !disableTargetOnName && battleAction.TargetData.EnableTargetNameID)
		{
			text = Smart.Format(GetLocalizedString(battleAction.TargetData.TargetNameID), text);
		}
		return text;
	}

	public string GetActionID()
	{
		if (enableCustomActionIDDescription)
		{
			return customActionIDDescription;
		}
		return actionID + "_D";
	}

	public string GetActionNameForDescription()
	{
		string text = "";
		text = ((!enableCustomActionIDNameForDescription) ? actionIDName : customActionIDNameForDescription);
		return GetLocalizedString(text);
	}

	public virtual string GetActionDescription(int amount, int bonusAmount, BattleAction battleAction, bool addTimelessTag, Dice dice = null, DiceFace diceFace = null, bool noRefreshedActionDescription = true, bool forgeDiceFace = false)
	{
		string text = "";
		if (bonusAmount > 0)
		{
			text = GetDescriptionWithBonusAmount(amount, bonusAmount, battleAction);
			text = GetDescriptionWithModifications(text, battleAction, addTimelessTag, diceFace, noRefreshedActionDescription, dice, forgeDiceFace);
			text += CheckGetDescriptionWithPurifyPreview(GetAmountModifiedString(amount, bonusAmount), battleAction);
		}
		else
		{
			text = GetAmountDescriptionNoBonusAmount(amount, battleAction);
			text = GetDescriptionWithModifications(text, battleAction, addTimelessTag, diceFace, noRefreshedActionDescription, dice, forgeDiceFace);
			text += CheckGetDescriptionWithPurifyPreview(amount.ToString(), battleAction);
		}
		return text + GetOncePerBattleDescription(battleAction);
	}

	private string GetDescriptionWithBonusAmount(int amount, int bonusAmount, BattleAction battleAction)
	{
		if (enableCustomDescription)
		{
			return customBattleActionDescription.GetActionDescription(GetAmountModifiedString(amount, bonusAmount), battleAction);
		}
		return Smart.Format(GetLocalizedActionDescription(), GetAmountModifiedString(amount, bonusAmount));
	}

	private string GetDescriptionWithModifications(string description, BattleAction battleAction, bool addTimelessTag, DiceFace diceFace, bool noRefreshedActionDescription, Dice dice, bool forgeDiceFace)
	{
		description += GetToDrawPoolOnDisposeActionDescription(battleAction);
		description += GetNotAffectedByDoomOrEmpowerDescription(battleAction);
		description += GetLockedActionDescription(battleAction);
		description += GetUnforgeableActionDescription(battleAction);
		if (!noRefreshedActionDescription)
		{
			description += GetRefreshedActionDescription();
		}
		if (addTimelessTag)
		{
			description += GetTimelessActionDescription(description, dice, battleAction.Timeless, forgeDiceFace);
		}
		if (diceFace != null)
		{
			if (diceFace.BattleAction is RerollAction)
			{
				description = RerollAtLeastOneDieFormattedDescription(description);
			}
			if (diceFace.BattleAction.name.Contains("Convert") || diceFace.BattleAction.name.Contains("Expertise"))
			{
				description = Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("ConvertAtLeastOneDie"), description.LowercaseFirst());
			}
		}
		return description;
	}

	protected string GetLocalizedActionDescription()
	{
		if (modded)
		{
			return moddedDescription;
		}
		return GetLocalizedString(ActionIDDescription);
	}

	protected string GetAmountModifiedString(int amount, int bonusAmount)
	{
		if (bonusAmount > 0)
		{
			return $"{amount + bonusAmount}({amount}+{bonusAmount})";
		}
		return amount.ToString();
	}

	private string GetAmountDescriptionNoBonusAmount(int amount, BattleAction battleAction)
	{
		if (enableCustomDescription)
		{
			return customBattleActionDescription.GetActionDescription(amount.ToString(), battleAction);
		}
		string text = GetLocalizedActionDescription();
		if (amount == -1)
		{
			if (text.Contains("{0"))
			{
				text = Smart.Format(text, 99999);
				text = text.Replace("99999", ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedX());
			}
			return text;
		}
		return Smart.Format(text, amount);
	}

	private string CheckGetDescriptionWithPurifyPreview(string amountModified, BattleAction battleAction)
	{
		if (!actionWithPreviewDescription)
		{
			return "";
		}
		if (GameScenesUtils.IsBattleScene())
		{
			if (ReferenceSingleton<GameStateManager>.Instance.CurrentState == ReferenceSingleton<GameStateManager>.Instance.PlayerUnlockablesState)
			{
				return "";
			}
			if (!showPreviewDescriptionEvenOutsideOfBattles && (ReferenceSingleton<GameStateManager>.Instance.CurrentState == ReferenceSingleton<GameStateManager>.Instance.PlayerRewardState || ReferenceSingleton<GameStateManager>.Instance.CurrentState == ReferenceSingleton<GameStateManager>.Instance.MapState))
			{
				return "";
			}
			string arg = "";
			if (previewDescriptionType == PreviewDescriptionType.NORMALPURIFY)
			{
				arg = Smart.Format(GetLocalizedString("Purify_D"), previewDescription.GetPreviewAmount(amountModified, battleAction));
			}
			if (previewDescriptionType == PreviewDescriptionType.NORMALCORRUPT)
			{
				arg = Smart.Format(GetLocalizedString("Corrupt_D"), previewDescription.GetPreviewAmount(amountModified, battleAction));
			}
			else if (previewDescriptionType == PreviewDescriptionType.TIMESPURIFY)
			{
				arg = Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedXTimes(), Smart.Format(GetLocalizedString("Purify_D"), amountModified), previewDescription.GetTimesPreviewAmount(amountModified, battleAction)).RemoveLast();
			}
			else if (previewDescriptionType == PreviewDescriptionType.TIMESCORRUPTION)
			{
				arg = Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedXTimes(), Smart.Format(GetLocalizedString("Corrupt_D"), amountModified), previewDescription.GetTimesPreviewAmount(amountModified, battleAction)).RemoveLast();
			}
			else if (previewDescriptionType == PreviewDescriptionType.OTHERACTION)
			{
				arg = ((!applyEffectOnAnyTarget) ? otherAction.GetActionDescription(previewDescription.GetPreviewAmount(amountModified, battleAction)).RemoveLast() : Smart.Format(GetLocalizedString("ApplyEffectPreview"), previewDescription.GetPreviewAmount(amountModified, battleAction), otherAction.GetActionNameForDescription()));
			}
			else if (previewDescriptionType == PreviewDescriptionType.CUSTOM)
			{
				arg = previewDescription.GetCustomPreviewDescription(amountModified, battleAction);
			}
			return string.Format("\n" + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedPreviewDescription(), arg);
		}
		return "";
	}

	public virtual string GetActionDescription(int amount, BattleAction battleAction, bool noRefreshedActionDescription = true)
	{
		return GetActionDescription(amount, 0, battleAction, addTimelessTag: false, null, null, noRefreshedActionDescription);
	}

	private string GetOncePerBattleDescription(BattleAction battleAction)
	{
		string result = "";
		if (battleAction.OncePerBattle)
		{
			result = "\n" + GetLocalizedString("Exhaust_N") + ".";
		}
		return result;
	}

	private string GetNotAffectedByDoomOrEmpowerDescription(BattleAction battleAction)
	{
		string text = "";
		if (notAffectedByDoom && notAffectedByEmpower)
		{
			text = "NotAffectedByDoomEmpower";
		}
		else if (notAffectedByDoom)
		{
			text = "NotAffectedByDoom";
		}
		else if (notAffectedByEmpower)
		{
			text = "NotAffectedByEmpower";
		}
		if (text != "")
		{
			return "\n" + GetLocalizedString(text);
		}
		return "";
	}

	private string GetUnforgeableActionDescription(BattleAction battleAction)
	{
		if (battleAction.NonForgeable)
		{
			string text = Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedDotAtTheEndFormat(), ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedUnforgeableKeyword());
			return "\n" + text;
		}
		return "";
	}

	private string GetLockedActionDescription(BattleAction battleAction)
	{
		if (battleAction.Locked)
		{
			string text = Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedDotAtTheEndFormat(), ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedLockedTagName());
			return "\n" + text;
		}
		return "";
	}

	private string GetToDrawPoolOnDisposeActionDescription(BattleAction battleAction)
	{
		if (battleAction.ToDrawPoolOnDisposeAction)
		{
			return "\n" + GetLocalizedString("ToDrawPoolOnDisposeAction");
		}
		return "";
	}

	private string GetTimelessActionDescription(string description, Dice dice, bool timeless, bool forgeDiceFace)
	{
		if (timeless && forgeDiceFace)
		{
			return GetTimelessActionDescription();
		}
		if (GameScenesUtils.IsBattleScene())
		{
			BattleHandler instance = ReferenceSingleton<BattleHandler>.Instance;
			if (instance.ActionDescriptionActionInstance != null && instance.ActionDescriptionActionInstance.DiceOwnerEnum != DiceOwnerEnum.COMPANION && ReferenceSingleton<BattleHandler>.Instance.ActionDescriptionActionInstance.DisableDiscard)
			{
				return GetTimelessActionDescription();
			}
		}
		if (timeless && dice != null && dice is PlayerDice)
		{
			return GetTimelessActionDescription();
		}
		return "";
		string GetTimelessActionDescription()
		{
			string text = Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedDotAtTheEndFormat(), GetLocalizedString("Timeless_N"));
			if (!description.Contains(text))
			{
				return "\n" + text;
			}
			return "";
		}
	}

	private string GetRefreshedActionDescription()
	{
		if (GameScenesUtils.IsBattleScene() && ReferenceSingleton<BattleHandler>.Instance.ActionDescriptionActionInstance != null && ReferenceSingleton<BattleHandler>.Instance.ActionDescriptionActionInstance is RuneInstance)
		{
			RuneInstance runeInstance = ReferenceSingleton<BattleHandler>.Instance.ActionDescriptionActionInstance as RuneInstance;
			if (ReferenceSingleton<BattleHandler>.Instance.PlayerCurrentRunes.refreshedRuneIndexes.Contains(runeInstance.Rune.index))
			{
				string text = Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedDotAtTheEndFormat(), GetLocalizedString("Refresh_N"));
				return "\n" + text;
			}
		}
		return "";
	}

	private string RerollAtLeastOneDieFormattedDescription(string description)
	{
		return Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("RerollAtLeastOneDie"), description.LowercaseFirst());
	}

	public Tag[] GetTags(bool addTimelessTag, Dice dice = null, BattleAction battleAction = null)
	{
		List<Tag> list = tags.DuplicateAsList();
		if (battleAction != null)
		{
			if (battleAction.Locked)
			{
				list.Add(ReferenceSingleton<AssetsReference>.Instance.LockedTag);
			}
			if (battleAction.NonForgeable)
			{
				list.Add(ReferenceSingleton<AssetsReference>.Instance.UnforgeableTag);
			}
		}
		Tag timelessTag = ReferenceSingleton<AssetsReference>.Instance.TimelessTag;
		if (addTimelessTag)
		{
			if (GameScenesUtils.IsBattleScene())
			{
				BattleHandler instance = ReferenceSingleton<BattleHandler>.Instance;
				if (instance.ActionDescriptionActionInstance != null)
				{
					if (tags.Contains(timelessTag))
					{
						if (instance.ActionDescriptionActionInstance.DiceOwnerEnum == DiceOwnerEnum.COMPANION || instance.ActionDescriptionActionInstance is RuneInstance)
						{
							list.Remove(timelessTag);
						}
					}
					else if (!tags.Contains(timelessTag) && instance.ActionDescriptionActionInstance.DiceOwnerEnum != DiceOwnerEnum.COMPANION && instance.ActionDescriptionActionInstance.DisableDiscard)
					{
						list.Add(timelessTag);
					}
					if (instance.ActionDescriptionActionInstance is RuneInstance)
					{
						RuneInstance runeInstance = instance.ActionDescriptionActionInstance as RuneInstance;
						if (instance.PlayerCurrentRunes.refreshedRuneIndexes.Contains(runeInstance.Rune.index))
						{
							list.Add(ReferenceSingleton<BattleHandler>.Instance.RefreshedTag);
						}
					}
				}
				else if (tags.Contains(timelessTag))
				{
					if (dice != null && dice is CompanionDice)
					{
						list.Remove(timelessTag);
					}
					else if (dice == null)
					{
						list.Remove(timelessTag);
					}
				}
			}
			else if (tags.Contains(timelessTag))
			{
				if (dice != null && dice is CompanionDice)
				{
					list.Remove(timelessTag);
				}
				else if (dice == null)
				{
					list.Remove(timelessTag);
				}
			}
		}
		else if (tags.Contains(timelessTag))
		{
			if (dice != null && dice is CompanionDice)
			{
				list.Remove(timelessTag);
			}
			else if (dice == null)
			{
				list.Remove(timelessTag);
			}
		}
		return list.ToArray();
	}

	public void PlaySFX()
	{
		if (EnableSFX)
		{
			ReferenceSingleton<SFXHandler>.Instance.PlaySFX(actionSFX);
		}
	}

	public void PlaySecondSFX()
	{
		if (EnableSecondSFX)
		{
			ReferenceSingleton<SFXHandler>.Instance.PlaySFX(actionSecondSFX);
		}
	}

	public void PlayLoopableSFX()
	{
		if (EnableLoopableSFX)
		{
			ReferenceSingleton<SFXHandler>.Instance.PlayLoopableSFX(ref loopableEventInstance, actionLoopableSFX);
		}
	}

	public void StopLoopableSFX()
	{
		if (EnableLoopableSFX)
		{
			ReferenceSingleton<SFXHandler>.Instance.StopSFX(ref loopableEventInstance);
		}
	}

	public void PlaySFXWithParameter(string parameter, int value)
	{
		if (EnableSFXWithParameter)
		{
			sfxWithParameterEventInstance = RuntimeManager.CreateInstance(SFXWithParameter);
			sfxWithParameterEventInstance.start();
			sfxWithParameterEventInstance.setParameterByName(parameter, value);
		}
	}

	public void SetSFXWithParameter(string parameter, int value, bool release)
	{
		if (EnableSFXWithParameter)
		{
			sfxWithParameterEventInstance.setParameterByName(parameter, value);
			if (release)
			{
				sfxWithParameterEventInstance.release();
			}
		}
	}

	private string GetLocalizedString(string id)
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(id);
	}

	public void SetupModdedBaseBattleActionData(string moddedDescription, BattleActionInteractionEnum battleActionInteractionEnum)
	{
		modded = true;
		this.moddedDescription = moddedDescription;
		battleActionInteractionEnums.Add(battleActionInteractionEnum);
	}
}
